// Beaver multiplication triples generated by the two servers from OT, reconstructed and checked on server 0:
//   - bitwise triples (BitwiseBmtBatchGenerator): XOR shares with a & b = c; count * width bits are packed into
//     64-bit triples,
//   - arithmetic triples (BmtBatchGenerator): additive shares with a * b = c modulo 2^width,
// at several widths. Prints FAIL or MISMATCH and exits non-zero on any error.

#include "parsecdb/comm/Comm.h"
#include "parsecdb/intermediate/BitwiseBmtBatchGenerator.h"
#include "parsecdb/intermediate/BmtBatchGenerator.h"
#include "parsecdb/utils/Log.h"
#include "parsecdb/utils/Math.h"
#include "parsecdb/utils/System.h"

#include <cstdint>
#include <string>
#include <vector>

using namespace parsecdb;

namespace {

// Server 1 sends its shares of every triple to server 0, which returns the opened (a, b, c) triples.
template <class Bmt>
bool openTriples(const std::vector<Bmt>& bmts, int tag, bool xorShares, int width, std::vector<int64_t>& a,
                 std::vector<int64_t>& b, std::vector<int64_t>& c) {
    std::vector<int64_t> mine;
    for (const auto& t : bmts) {
        mine.insert(mine.end(), {t._a, t._b, t._c});
    }
    if (Comm::rank() == 1) {
        Comm::send(mine, 64, 0, tag);
        return false;
    }
    std::vector<int64_t> theirs;
    Comm::receive(theirs, 64, 1, tag);
    for (size_t i = 0; i < bmts.size(); ++i) {
        auto open = [&](size_t k) {
            return xorShares ? (mine[3 * i + k] ^ theirs[3 * i + k])
                             : Math::ringAdd(mine[3 * i + k], theirs[3 * i + k], width);
        };
        a.push_back(open(0));
        b.push_back(open(1));
        c.push_back(open(2));
    }
    return true;
}

bool testBitwise(int task, int count, int width) {
    BitwiseBmtBatchGenerator gen(count, width, task, 0);
    gen.execute();
    std::vector<int64_t> a, b, c;
    if (!openTriples(gen._bmts, task * 1000 + 1, true, width, a, b, c)) {
        return true;
    }
    int mismatches = 0;
    for (size_t i = 0; i < a.size(); ++i) {
        if ((a[i] & b[i]) != c[i] && ++mismatches <= 10) {
            Log::e("MISMATCH bitwise width={} i={}: a&b={} c={}", width, i, static_cast<uint64_t>(a[i] & b[i]),
                   static_cast<uint64_t>(c[i]));
        }
    }
    const int expectedTriples = (count * width + 63) / 64;
    if (static_cast<int>(a.size()) != expectedTriples) {
        Log::e("FAIL bitwise width={}: {} triples, expected {}", width, a.size(), expectedTriples);
        ++mismatches;
    }
    Log::i("[bitwise BMT count={} width={}] {}", count, width, mismatches == 0 ? "ok" : "FAIL");
    return mismatches == 0;
}

bool testArithmetic(int task, int count, int width) {
    BmtBatchGenerator gen(count, width, task, 0);
    gen.execute();
    std::vector<int64_t> a, b, c;
    if (!openTriples(gen._bmts, task * 1000 + 1, false, width, a, b, c)) {
        return true;
    }
    int mismatches = 0;
    for (size_t i = 0; i < a.size(); ++i) {
        const int64_t product = Math::ringMultiply(a[i], b[i], width);
        if (product != c[i] && ++mismatches <= 10) {
            Log::e("MISMATCH arithmetic width={} i={}: a*b={} c={}", width, i, product, c[i]);
        }
    }
    if (static_cast<int>(a.size()) != count) {
        Log::e("FAIL arithmetic width={}: {} triples, expected {}", width, a.size(), count);
        ++mismatches;
    }
    Log::i("[arithmetic BMT count={} width={}] {}", count, width, mismatches == 0 ? "ok" : "FAIL");
    return mismatches == 0;
}

} // namespace

int main(int argc, char** argv) {
    System::init(argc, argv);
    bool ok = true;
    if (Comm::isServer()) {
        const int task = System::nextTask();
        int round = 0;
        for (int width : {64, 16}) {
            ok &= testBitwise(task + ++round, 100, width);
        }
        for (int width : {1, 8, 32, 64}) {
            ok &= testArithmetic(task + ++round, 200, width);
        }
        Log::i("[BMT generation] {}", ok ? "PASS" : "FAIL");
    }
    System::finalize();
    return ok ? 0 : 1;
}
